// Exercise eastl::align behavior with a small heap buffer; validate pointer/space updates.
{
    const size_t bufSize = 256;
    void* buffer = ::operator new[](bufSize);
    void* ptr = buffer;
    size_t space = bufSize;

    // Choose power-of-two alignment in [1, 64]
    unsigned int pow2 = (unsigned int)(*FUZZ_PARAM(unsigned int) % 7); // 0..6
    size_t alignment = size_t(1) << pow2; // 1,2,4,8,16,32,64
    size_t size = (size_t)(*FUZZ_PARAM(unsigned int) % 128); // requested block size

    void* aligned = eastl::align(alignment, size, ptr, space);

    if (size == 0) {
        // std::align guarantees: if size==0, return current ptr (already aligned by definition)
        FUZZ_ASSERT(aligned == ptr, "size==0 should return current pointer");
    }

    if (aligned) {
        // Validate alignment and bounds; ptr/space must be updated to aligned start and remaining space
        uintptr_t addr = (uintptr_t)aligned;
        FUZZ_ASSERT((addr % alignment) == 0, "returned pointer must satisfy alignment");
        FUZZ_ASSERT(space <= bufSize, "space must not exceed original buffer size");
        FUZZ_ASSERT(((uint8_t*)aligned) >= ((uint8_t*)buffer), "aligned must be within buffer start");
        FUZZ_ASSERT(((uint8_t*)aligned + size) <= ((uint8_t*)buffer + bufSize), "aligned region must fit inside buffer");
    } else {
        // On failure, ptr and space must be unchanged.
        FUZZ_ASSERT(ptr == buffer && space == bufSize, "on failure, ptr/space must remain unchanged");
    }

    ::operator delete[](buffer);
    // Validation: Covers both success and failure paths with power-of-two alignment.
}

// Exercise eastl::align_advance; validate optional outputs when alignment succeeds.
{
    const size_t bufSize = 256;
    void* buffer = ::operator new[](bufSize);

    void* ptrAdvanced = (void*)(uintptr_t)0xDEADBEEF; // sentinels to detect writes
    size_t spaceReduced = 0xBEEFCAFEu;

    void* ptrIn = buffer;
    size_t spaceIn = bufSize;

    unsigned int pow2 = (unsigned int)(*FUZZ_PARAM(unsigned int) % 7);
    size_t alignment = size_t(1) << pow2; // 1..64
    size_t size = (size_t)(*FUZZ_PARAM(unsigned int) % 128);

    void* aligned = eastl::align_advance(alignment, size, ptrIn, spaceIn, &ptrAdvanced, &spaceReduced);

    if (aligned) {
        uintptr_t addr = (uintptr_t)aligned;
        FUZZ_ASSERT((addr % alignment) == 0, "aligned pointer must satisfy alignment");
        FUZZ_ASSERT(((uint8_t*)aligned + size) <= ((uint8_t*)buffer + bufSize), "aligned block must fit in buffer");
        // Optional outputs must reflect the advanced pointer (aligned + size) and remaining space
        FUZZ_ASSERT(ptrAdvanced == ((uint8_t*)aligned + size), "ptrAdvanced must equal aligned + size");
        FUZZ_ASSERT(spaceReduced <= bufSize, "spaceReduced must not exceed buffer size");
    } else {
        // On failure, optional outputs must not be written per contract; check sentinels unchanged.
        FUZZ_ASSERT(ptrAdvanced == (void*)(uintptr_t)0xDEADBEEF, "ptrAdvanced must remain unchanged on failure");
        FUZZ_ASSERT(spaceReduced == 0xBEEFCAFEu, "spaceReduced must remain unchanged on failure");
    }

    ::operator delete[](buffer);
    // Validation: Covers success/failure, and verifies optional outputs only on success.
}

