// Instantiate concrete types for the template to exercise multiple constructors.
// Key=int, T=int, Compare=eastl::less<int>, Allocator=default.
// Constraints: Compare provides strict weak ordering on int; int is comparable; int is default-constructible.
{
    // Default allocator constructor
    eastl::map<int, int> m_default;

    // Comparator + allocator constructor
    eastl::less<int> cmp; // Strict-weak-ordering for int
    eastl::map<int, int> m_cmp_alloc(cmp);

    // Copy constructor
    // Populate a source map with a few elements to make copy meaningful
    int const (&karr)[6] = *FUZZ_PARAM(int[6]);
    int const (&varr)[6] = *FUZZ_PARAM(int[6]);
    for (int i = 0; i < 6; ++i) {
        m_cmp_alloc.insert(eastl::pair<const int, int>(karr[i], varr[i]));
    }
    eastl::map<int, int> m_copy(m_cmp_alloc);

    // Move constructor (x becomes valid but unspecified)
    eastl::map<int, int> m_move(eastl::move(m_copy));

    // Move constructor with allocator
    eastl::map<int, int> m_move_alloc(eastl::move(m_move), m_move.get_allocator());

    // initializer_list constructors
    // Build a small initializer_list-like array and construct
    eastl::pair<const int, int> init_pairs[3] = {
        {karr[0], varr[0]}, {karr[1], varr[1]}, {karr[2], varr[2]}
    };
    eastl::map<int, int> m_ilist({init_pairs[0], init_pairs[1], init_pairs[2]});
    eastl::map<int, int> m_ilist_alloc({init_pairs[0], init_pairs[1], init_pairs[2]}, m_ilist.get_allocator());

    // Basic sanity assertions that constructed maps are valid containers: size() queries shouldn't fail.
    (void)m_default.size();
    (void)m_cmp_alloc.size();
    (void)m_move_alloc.size();
    (void)m_ilist.size();
    (void)m_ilist_alloc.size();
}
// Validation: Stubs construct maps via all listed constructors using valid comparator/allocator and random data; no inputs or outputs are persisted.

