// Harness for eastl::visit with a single variant
using V = eastl::variant<int, long, double>;

V v;
unsigned sel = (unsigned)(*FUZZ_PARAM(unsigned int) % 3);
if (sel == 0)      v = (int)*FUZZ_PARAM(int);
else if (sel == 1) v = (long)*FUZZ_PARAM(long);
else               v = (double)*FUZZ_PARAM(double);

// Visitor that is callable for all alternatives and returns a uniform type (int)
auto visitor = [](auto&& x) -> int {
    using T = eastl::remove_cv_t<eastl::remove_reference_t<decltype(x)>>;
    if constexpr (eastl::is_same_v<T, int>) {
        return x + 1;
    } else if constexpr (eastl::is_same_v<T, long>) {
        return (int)(x ^ 0x5a5a5a5aL);
    } else { // double
        double y = x * 1.5;
        return (int)(y);
    }
};

volatile int r = eastl::visit(visitor, v);
(void)r;

