// Attempt to extract the stored value by value using a type known via attributes.
// On mismatch, any_cast invokes DoBadAnyCast which may throw or crash depending on configuration.
// To avoid invoking the failure path, we require a known matching type_tag; otherwise we bail.
{
    int tag = FUZZ_GET_ATTR_INT(operand, "type_tag");
    if(tag == 0){
        // Unknown or empty; can't safely call any_cast without risking a crash in non-exception builds.
        FUZZ_BAIL();
    }

    // Dispatch to the exact contained type to ensure success across configurations.
    switch(tag){
        case 1: {
            (void)eastl::any_cast<int>(static_cast<const eastl::any&>(*operand));
            break;
        }
        case 2: {
            (void)eastl::any_cast<double>(static_cast<const eastl::any&>(*operand));
            break;
        }
        case 3: {
            (void)eastl::any_cast<eastl::string>(static_cast<const eastl::any&>(*operand));
            break;
        }
        default: {
            // Unknown tag value; avoid unsafe call
            FUZZ_BAIL();
        }
    }
    FUZZ_SET_ATTR_INT(operand, "last_cast_ok", 1);
    // Validation: We only cast when a matching type is known; operand persists and attributes updated.
}

// Perform an unchecked cast; must only be used when we know the exact contained type.
