    switch(tag){
        case 1: {
            const int* pi = eastl::unsafe_any_cast<int>(static_cast<const eastl::any*>(pAny));
            FUZZ_ASSERT(pi != nullptr, "unsafe_any_cast<int> returned null");
            // Touch value to validate pointer usability
            volatile int sink = *pi; (void)sink;
