        case 2: {
            const double* pd = eastl::unsafe_any_cast<double>(static_cast<const eastl::any*>(pAny));
            FUZZ_ASSERT(pd != nullptr, "unsafe_any_cast<double> returned null");
            volatile double sink = *pd; (void)sink;
