        case 3: {
            const eastl::string* ps = eastl::unsafe_any_cast<eastl::string>(static_cast<const eastl::any*>(pAny));
            FUZZ_ASSERT(ps != nullptr, "unsafe_any_cast<string> returned null");
            // Light observation to avoid heavy allocations
