import random
import struct
from typing import List

# We generate arbitrary bytes that are often interpreted as std::string payloads
# and sometimes as byte buffers for eastl::span over unsigned char. We try to
# provide varied, but valid content that can exercise algorithms: mixtures of
# ASCII, repeated runs, sorted/unsorted segments, edge bytes, and random data.

MAX_TOTAL = 4096

def _rand_ascii(r: random.Random, n: int) -> bytes:
    # Printable ASCII plus some whitespace
    charset = [
        *range(0x20, 0x7f),  # printable
        0x09, 0x0a, 0x0d,    # tab, LF, CR
    ]
    return bytes(r.choice(charset) for _ in range(n))

def _rand_bytes(r: random.Random, n: int) -> bytes:
    return r.randbytes(n)

def _repeated(r: random.Random, n: int) -> bytes:
    if n == 0:
        return b""
    b = r.randrange(256)
    return bytes([b]) * n

def _pattern_ascending(n: int, start: int = 0) -> bytes:
    return bytes(((start + i) & 0xff) for i in range(n))

def _pattern_descending(n: int, start: int = 255) -> bytes:
    return bytes(((start - i) & 0xff) for i in range(n))

def _palindrome(r: random.Random, n: int) -> bytes:
    if n <= 1:
        return _rand_bytes(r, n)
    half = (n + 1) // 2
    left = _rand_bytes(r, half)
    if n % 2 == 0:
        return left + left[::-1]
    return left + left[:-1][::-1]

def _utf16_pack(r: random.Random, units: int) -> bytes:
    # Produce bytes that are plausible UTF-16 sequences (mix of ASCII and surrogate-like values)
    out = bytearray()
    for _ in range(units):
        mode = r.randrange(4)
        if mode == 0:
            v = r.randrange(0x0000, 0x0080)
        elif mode == 1:
            v = r.randrange(0x0080, 0x07FF)
        elif mode == 2:
            # BMP excluding surrogates
            v = r.randrange(0x0800, 0xD7FF)
        else:
            # Place some surrogate-range code units as raw units (valid as code units for hashing)
            v = r.randrange(0xD800, 0xDFFF)
        out += struct.pack('<H', v & 0xFFFF)
    return bytes(out)

def _utf32_pack(r: random.Random, units: int) -> bytes:
    out = bytearray()
    for _ in range(units):
        mode = r.randrange(4)
        if mode == 0:
            v = r.randrange(0x0000, 0x0080)
        elif mode == 1:
            v = r.randrange(0x0080, 0x07FF)
        elif mode == 2:
            v = r.randrange(0x0800, 0xFFFF)
        else:
            v = r.randrange(0x10000, 0x10FFFF)
        out += struct.pack('<I', v)
    return bytes(out)

def _make_chunks(r: random.Random) -> List[bytes]:
    chunks: List[bytes] = []
    # Small seeds for various algorithms using up to 64 bytes
    sizes = [
        r.randrange(0, 5),
        r.randrange(5, 17),
        r.randrange(0, 33),
        r.randrange(0, 65),
    ]
    for n in sizes:
        choice = r.randrange(8)
        if choice == 0:
            chunks.append(_rand_ascii(r, n))
        elif choice == 1:
            chunks.append(_rand_bytes(r, n))
        elif choice == 2:
            chunks.append(_repeated(r, n))
        elif choice == 3:
            chunks.append(_pattern_ascending(n, r.randrange(256)))
        elif choice == 4:
            chunks.append(_pattern_descending(n, r.randrange(256)))
        elif choice == 5:
            chunks.append(_palindrome(r, n))
        elif choice == 6:
            # Include zeros and 0xFF frequently to exercise comparisons/copies
            base = bytes([0x00, 0xFF])
            rep = (n + 1) // 2
            chunks.append((base * rep)[:n])
        else:
            # Mixed small pattern
            block = bytes([0, 1, 2, 3, 4, 5, 250, 251, 252, 253, 254, 255])
            rep = (n + len(block) - 1) // len(block)
            chunks.append((block * rep)[:n])

    # Larger buffer for span tests (up to ~2KB)
    big_len = r.randrange(0, 2049)
    # Compose big buffer from segments to include structure
    big = bytearray()
    while len(big) < big_len:
        mode = r.randrange(6)
        remain = big_len - len(big)
        take = min(remain, r.randrange(16, 257))
        if mode == 0:
            big += _rand_bytes(r, take)
        elif mode == 1:
            big += _pattern_ascending(take, r.randrange(256))
        elif mode == 2:
            big += _pattern_descending(take, r.randrange(256))
        elif mode == 3:
            big += _repeated(r, take)
        elif mode == 4:
            big += _palindrome(r, take)
        else:
            # include runs of zeros to test empty-like content inside
            z = min(take, r.randrange(0, take + 1))
            big += bytes([0]) * z + _rand_ascii(r, take - z)
    chunks.append(bytes(big))

    # Add plausible UTF-16 and UTF-32 packed sequences to exercise hashing views when bytes are reinterpreted
    if r.random() < 0.7:
        u16_units = r.randrange(0, 513)
        chunks.append(_utf16_pack(r, u16_units))
    if r.random() < 0.7:
        u32_units = r.randrange(0, 257)
        chunks.append(_utf32_pack(r, u32_units))

    return chunks

def generate(seed: int) -> bytes:
    r = random.Random(seed)
    chunks = _make_chunks(r)

    # Join with small separators that include edge bytes to diversify
    seps = [b"", b"\x00", b"\xff", b"\n", b"\x00\xff"]
    out = bytearray()
    for i, c in enumerate(chunks):
        out += c
        if i + 1 < len(chunks):
            out += seps[r.randrange(len(seps))]
        if len(out) > MAX_TOTAL:
            break

    # Ensure not exceeding maximum
    return bytes(out[:MAX_TOTAL])
